use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Generate new lib.rs that re-exports the split declarations in the output directory"] fn generate_output_lib_rs (paths : & CratePaths) -> Result < () > { let output_lib_path = paths . decls_output_dir . parent () . unwrap () . join ("lib.rs") ; let new_lib_content = format ! (r#"// Generated by split-decls-rs
// Re-exports all split declarations

pub mod decls {{
    include!("decls/_decl_module_invocation.rs");
}}
pub use decls::*;

// Re-export prelude macros if available

pub use introspector_decl2_macros::*;
"#) ; fs :: create_dir_all (output_lib_path . parent () . unwrap ()) . context ("Failed to create output src directory") ? ; let initial_content = add_generated_rust_header ! (new_lib_content . as_str () , file ! () , line ! ()) ; match format_rust_file (& initial_content , & output_lib_path) { Ok (formatted_content) => { fs :: write (& output_lib_path , formatted_content) . context (format ! ("Failed to write formatted output lib.rs at {}" , output_lib_path . display ())) ? ; } , Err (e) => { let error_comment = format ! ("// !!! Formatting failed for this module. The following code is unformatted. !!!\n\
                // !!! Error: {} !!!\n\n" , e) ; let content_with_error_comment = error_comment + & initial_content ; fs :: write (& output_lib_path , content_with_error_comment) . context (format ! ("Failed to write unformatted output lib.rs with error comment at {}" , output_lib_path . display ())) ? ; error ! ("\n<blip style='color:red'>Formatting error for output lib.rs (written to {})</blip>" , output_lib_path . display ()) ; } } println ! ("Generated output lib.rs at {}" , output_lib_path . display ()) ; Ok (()) }